import { z } from "zod";

/**
 * Case ground truth. Generated by the LLM, parsed with these schemas, then
 * checked by the rule checks and the solver before a game may use it.
 * Only the game server ever holds a full CaseFile.
 */

export const TimelineEventSchema = z.object({
  t: z.string().describe("24h clock time, HH:MM"),
  event: z.string(),
});

export const SuspectSchema = z.object({
  id: z.string().describe("s1, s2, ..."),
  name: z.string(),
  role: z.string().describe("e.g. business partner, nephew, cook"),
  relationshipToVictim: z.string(),
  bio: z.string().describe("one public sentence shown on the suspect card"),
  persona: z.string().describe("personality and speaking style"),
  motive: z.string(),
  alibi: z.string().describe("what the suspect claims they were doing at the time of death"),
  secret: z
    .string()
    .nullable()
    .describe("embarrassing non-murder secret that makes an innocent look guilty; null for the killer"),
  timeline: z.array(TimelineEventSchema).describe("what this suspect really did that evening, in time order"),
  witnessed: z.array(z.string()).describe("things this suspect personally saw or heard"),
});

export const ClueSchema = z.object({
  id: z.string().describe("c1, c2, ..."),
  round: z.number().int().describe("interrogation round in which the clue unlocks (1-3)"),
  text: z.string(),
  pointsTo: z.string().nullable().describe("suspect id this clue implicates, or null"),
  contradicts: z
    .string()
    .nullable()
    .describe('what this clue contradicts, e.g. "s3.alibi", or null'),
  isKey: z.boolean().describe("true for clues that decisively implicate the killer"),
});

export const VictimSchema = z.object({
  name: z.string(),
  description: z.string(),
  cause: z.string(),
  timeOfDeath: z.string().describe("HH:MM"),
  foundBy: z.string(),
  scene: z.string().describe("where the body was found and what the scene looked like"),
});

export const CaseFileSchema = z.object({
  title: z.string(),
  theme: z.string(),
  setting: z.string().describe("two or three sentences setting the scene"),
  victim: VictimSchema,
  killerId: z.string(),
  suspects: z.array(SuspectSchema),
  clues: z.array(ClueSchema),
  solution: z.object({
    summary: z.string().describe("how and why the killer did it"),
    timeline: z.array(TimelineEventSchema).describe("the true timeline of the evening"),
  }),
});

export type TimelineEvent = z.infer<typeof TimelineEventSchema>;
export type Suspect = z.infer<typeof SuspectSchema>;
export type Clue = z.infer<typeof ClueSchema>;
export type Victim = z.infer<typeof VictimSchema>;
export type CaseFile = z.infer<typeof CaseFileSchema>;

/** What a single suspect agent is allowed to know. Built server-side. */
export interface SuspectSlice {
  suspectId: string;
  name: string;
  role: string;
  relationshipToVictim: string;
  persona: string;
  motive: string;
  alibi: string;
  secret: string | null;
  timeline: TimelineEvent[];
  witnessed: string[];
  isKiller: boolean;
  /** Public scene facts every character knows. */
  setting: string;
  victim: { name: string; description: string; cause: string; foundBy: string; scene: string };
  /** Names and roles of everyone else - no secrets. */
  cast: { id: string; name: string; role: string }[];
}
